sys_variable_value.value:
(function execute(inputs, outputs) {
// ... code ...
var customercode = inputs.customercode;
var req = new sn_ws.RESTMessageV2();
    // Unescape the endpoint (real '&' not &amp;)
    req.setEndpoint('https://speed.eye2serve.com:7777/XISOAPAdapter/MessageServlet?senderParty=&senderService=BusService_SFA&receiverParty=&receiverService=BS_GRP300&interface=MI_CustOutstanding_USS&interfaceNamespace=http://CustOutstanding:uss.com');
    // Correct headers for SOAP 1.1
    req.setRequestHeader('Content-Type', 'text/xml; charset=utf-8');
    req.setRequestHeader('Accept', 'text/xml');
req.setHttpMethod('POST');
    var body =
      '<?xml version="1.0" encoding="UTF-8"?>' +
      '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:cus="http://CustOutstanding:uss.com">' +
      '  <soapenv:Header/>' +
      '  <soapenv:Body>' +
      '    <cus:MT_CustOutstanding_Req_USS>' +
      // NOTE: Depending on the provider’s schema, this child element may need the 'cus' prefix as well.
      // If they require namespaced children, change to <cus:Customer_Code>...</cus:Customer_Code>
      '      <Customer_Code>'+customercode+'</Customer_Code>' +
      '    </cus:MT_CustOutstanding_Req_USS>' +
      '  </soapenv:Body>' +
      '</soapenv:Envelope>';

    req.setRequestBody(body);
    req.setBasicAuth('po_wsdl', 'Poqa@2019');

    // Optional: timeout and MID routing
    req.setHttpTimeout(60000);
    // req.setMIDServer('YOUR_MID_NAME'); // if endpoint is reachable only via MID

    var res = req.execute();
    var status = res.getStatusCode();
    var bodyOut = res.getBody();
    var err = res.getErrorMessage();

   // gs.info('[SOAP via REST] HTTP ' + status);
   // gs.info(bodyOut);
	
var x = new XMLDocument2();
x.parseXML(bodyOut);

var cust = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='Customer']");
var outstanding = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='OUTSTANDING']");
var AGEING0_3 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING0_3']");
var AGEING4_7 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING4_7']");
var AGEING8_21 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING8_21']");
var AGEING22_30 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING22_30']");
var AGEING31_45 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING31_45']");
var AGEING46_60 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING46_60']");
var AGEING61_75 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING61_75']");
var AGEING76_90 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING76_90']");
var AGEING_GT90 = x.getNodeText("//*[local-name()='OutstandingResponse']/*[local-name()='Details']/*[local-name()='AGEING_GT90']");

//gs.info('Customer=' + cust + ', OUTSTANDING=' + outstanding+' ,AGEING_GT90: '+AGEING_GT90);

outputs.outstanding = outstanding;
outputs.age_3 = AGEING0_3;
outputs.age_7 = AGEING4_7;
outputs.age_21 = AGEING8_21;
outputs.age_30 = AGEING22_30;
outputs.age_45= AGEING31_45;
outputs.age_60= AGEING46_60;
outputs.age_75= AGEING61_75;
outputs.age_90= AGEING76_90;
outputs.age_GT90= AGEING_GT90;

})(inputs, outputs);

